    "content": "全国总工会11月27日消息，全国总工会、人力资源社会保障部、国家卫生健康委、中国企业联合会/中国企业家协会、全国工商联近日联合印发了《家庭友好型工作场所建设工作指引（试行）》（以下简称《指引》）。 全总介绍，家庭友好型工作场所是指用人单位通过完善优化工作管理制度，打造安全有尊严的、有利于职工身心健康的职场环境，支持男女职工平衡工作、家庭和个人生活，保障职工在身心健康的状态下投入工作的场所。 全总指出，《指引》充分发挥三方机制在构建和谐劳动关系方面的作用，首次在政策层面提出理念态度友好、职业发展友好、生育保护友好、照…"
