    "description": "中新网北京11月27日电 (记者 孙自法)中俄“图们江之路”联合工作组2026年度工作会议暨中俄地理学会双边工作交流会近日在北京举行。会议提供媒体的信息透露，2027年“金砖国家地理学家日”系列活动将在中国举行，2027年8月中旬至9月下旬，将在北京举办“金砖国家地理学家日”全球主场活动。",
    "content": "中新网北京11月27日电 (记者 孙自法)中俄“图们江之路”联合工作组2026年度工作会议暨中俄地理学会双边工作交流会近日在北京举行。会议提供媒体的信息透露，2027年“金砖国家地理学家日”系列活动将在中国举行，2027年8月中旬至9月下旬，将在北京举办“金砖国家地理学家日”全球主场活动。"
