    "description": "新华社布鲁塞尔11月27日电（记者张兆卿 朱昊晨）欧盟特别峰会27日凌晨在布鲁塞尔闭幕。欧洲理事会主席科斯塔在会后记者会上表示，欧盟领导人未能就2028年至2034年多年期财政框架达成一致。 科斯塔说，部分成员国要求进一步压低预算总额，多数成员国反对继续削减，一些国家还提议恢复折中方案中削减的部分拨款，尤其是用于缩小地区发展差距的资金。 德国、荷兰等向欧盟预算缴款多于所得拨款的国家主张进一步压低预算总额。德国总理默茨26日晚表示，各国在…",
    "content": "新华社布鲁塞尔11月27日电（记者张兆卿 朱昊晨）欧盟特别峰会27日凌晨在布鲁塞尔闭幕。欧洲理事会主席科斯塔在会后记者会上表示，欧盟领导人未能就2028年至2034年多年期财政框架达成一致。 科斯塔说，部分成员国要求进一步压低预算总额，多数成员国反对继续削减，一些国家还提议恢复折中方案中削减的部分拨款，尤其是用于缩小地区发展差距的资金。 德国、荷兰等向欧盟预算缴款多于所得拨款的国家主张进一步压低预算总额。德国总理默茨26日晚表示，各国在预算规模和资金分配上仍有很大分歧。与会领导人商定，取消原定于27日上午举行的会议…"
