    "content": "新华社渥太华11月26日电（记者 林威）由加拿大近30万民众实名联署、呼吁加政府驱逐美国驻加大使皮特·胡克斯特拉的请愿书26日已被提交加拿大国会众议院。 加拿大绿党领袖伊丽莎白·梅当天将该请愿书提交至众议院。众议院网站显示，请愿书由285993人实名联署。根据众议院议事规则，请愿书提交至众议院后，加拿大联邦政府必须在45天内作出正式回应。 梅当日在国会呈递请愿书时称胡克斯特拉为“最不懂外交的外交官”。她说，广大加拿大人已明确表达其不受欢迎的态度，同时讽刺地祝他感恩节快乐，认为他“生活在另一个国家会更开心”。 这项请…"
