    "description": "36氪获悉，据商务部消息，11月26日下午，商务部副部长兼中华人民共和国国际贸易谈判副代表凌激与丹麦外交部常务国务秘书叶普在丹麦哥本哈根共同主持召开中国—丹麦经贸联委会第25次会议。中国驻丹麦大使王雪峰以及中丹两国经济界代表参加。凌激表示，近年来，中丹贸易保持增长，双向投资稳步扩大。中方愿与丹方深化绿色低碳、数字智能、医药健康、服务贸易等领域务实合作。中丹均支持自由贸易和多边贸易体制，中方愿推动中欧经贸关系向上平衡，欧方应审慎出台经贸限…",
    "content": "36氪获悉，据商务部消息，11月26日下午，商务部副部长兼中华人民共和国国际贸易谈判副代表凌激与丹麦外交部常务国务秘书叶普在丹麦哥本哈根共同主持召开中国—丹麦经贸联委会第25次会议。中国驻丹麦大使王雪峰以及中丹两国经济界代表参加。凌激表示，近年来，中丹贸易保持增长，双向投资稳步扩大。中方愿与丹方深化绿色低碳、数字智能、医药健康、服务贸易等领域务实合作。中丹均支持自由贸易和多边贸易体制，中方愿推动中欧经贸关系向上平衡，欧方应审慎出台经贸限制措施，克制使用贸易救济工具，为中欧企业合作提供稳定性和确定性。希望丹方为中资企…"
