    "content": "新华社华盛顿11月26日电（记者黄强 徐剑梅）美国总统特朗普26日在佛罗里达州海湖庄园回答媒体提问时说，尚未在伊朗镐山发现任何实质性活动。 特朗普说，美国正试图给伊朗一个“展现明智”的机会。他说，他相信伊朗还有些底牌，美方一直在严密监视伊方行动，“我们目前还没有看到那里有任何实质性活动”。他还表示，如果能达成协议最好。 在此之前，特朗普在感恩节同美军官兵通话时表示，美方将给伊朗领导层充分的机会去达成协议，但“我不确定他们是否会把握住这个机会”。他还称美国对伊朗的胜利“已近在咫尺”。 镐山位于伊朗中部伊斯法罕省纳坦兹…"
