    "content": "近日，云南省保山市龙陵小黑山省级自然保护区工作人员在收集整理红外相机资料时，意外发现一种长相奇特的小动物。经国家林业和草原局西南调查规划院助理工程师张凌寒鉴定，确定其为劳亚食虫目猬科林猬属动物王氏林猬（也称“高黎贡林猬”）。 小黑山省级自然保护区红外相机拍到的王氏林猬。 王氏林猬是2018年发表的新物种，这次是王氏林猬时隔8年再次现身，也是该物种在小黑山保护区的首次记录，为该保护区新记录物种。 资料显示，2003年，云南高黎贡山国家级自然保护区保山管护局工作人员在保护区南段山区发现野生刺猬种群，此后中国科学院昆明动…"
