    "description": "香港大埔宏福苑大火发生一周年，大批死者家属、宏福苑居民及市民自发前往火灾现场附近献花悼念，直至隔天凌晨仍有30人留守哀悼。香港当局清理部分悼念花束的做法引起一些市民不满，港府解释，此举旨在腾出空间，方便更多市民献花。 综合香港《明报》《星岛日报》及香港01报道，星期四（11月26日）是造成168人罹难的宏福苑大火一周年。官方没有举行悼念仪式，但从当天早上起，陆续有市民自发带着鲜花、心意卡、食物及玩具等物品，到宏福苑附近的广福休憩处悼念死…",
    "content": "香港大埔宏福苑大火发生一周年，大批死者家属、宏福苑居民及市民自发前往火灾现场附近献花悼念，直至隔天凌晨仍有30人留守哀悼。香港当局清理部分悼念花束的做法引起一些市民不满，港府解释，此举旨在腾出空间，方便更多市民献花。 综合香港《明报》《星岛日报》及香港01报道，星期四（11月26日）是造成168人罹难的宏福苑大火一周年。官方没有举行悼念仪式，但从当天早上起，陆续有市民自发带着鲜花、心意卡、食物及玩具等物品，到宏福苑附近的广福休憩处悼念死者。香港政务司司长陈国基此前说，政府不会妨碍市民进行合法的悼念活动。 入夜后，随…"
