    "description": "新华社莫斯科11月26日电（记者栾海）俄罗斯总统普京26日在莫斯科表示，为争取在人工智能（AI）研发方面获得领先地位，俄需更新相关国家战略；在支持开发俄自主AI模型方面，则需落实四项要求。 据俄总统网站26日发布的消息，普京当天在与哈萨克斯坦总统托卡耶夫一同出席“人工智能世界之旅”大会时发表讲话说，若想在AI研发方面取得领先地位，就要最大限度实现人与自主系统协同运作，并为此重构管理和生产流程。依据这一思路，俄需更新“2036年前俄人工智…",
    "content": "新华社莫斯科11月26日电（记者栾海）俄罗斯总统普京26日在莫斯科表示，为争取在人工智能（AI）研发方面获得领先地位，俄需更新相关国家战略；在支持开发俄自主AI模型方面，则需落实四项要求。 据俄总统网站26日发布的消息，普京当天在与哈萨克斯坦总统托卡耶夫一同出席“人工智能世界之旅”大会时发表讲话说，若想在AI研发方面取得领先地位，就要最大限度实现人与自主系统协同运作，并为此重构管理和生产流程。依据这一思路，俄需更新“2036年前俄人工智能国家战略”，审批相关国家行动计划。 普京指出，发展俄人工智能技术的一项要务是进…"
