    "description": "新华社济南11月27日电 还记得从清亮黏稠的糖水中，捞出一块金黄鲜亮的黄桃，香甜滋味瞬间从舌尖润到心底的感觉吗？从待客访友的高端礼品，到一度被冷落的高糖食品，再到搭配酸奶、制作甜品的百搭配料，一路起起伏伏的水果罐头，好像从未远离过我们的生活。 但你是否知道，这份舌尖上的甜蜜，有三分之一来自山东一个叫“地方”的小镇？中国罐头工业协会数据显示，全国每3瓶果品罐头，就有1瓶来自地方镇，因此业内有“有罐头的地方，就有‘地方’的罐头”的说法。 位…",
    "content": "新华社济南11月27日电 还记得从清亮黏稠的糖水中，捞出一块金黄鲜亮的黄桃，香甜滋味瞬间从舌尖润到心底的感觉吗？从待客访友的高端礼品，到一度被冷落的高糖食品，再到搭配酸奶、制作甜品的百搭配料，一路起起伏伏的水果罐头，好像从未远离过我们的生活。 但你是否知道，这份舌尖上的甜蜜，有三分之一来自山东一个叫“地方”的小镇？中国罐头工业协会数据显示，全国每3瓶果品罐头，就有1瓶来自地方镇，因此业内有“有罐头的地方，就有‘地方’的罐头”的说法。 位于沂蒙山区的临沂市平邑县地方镇，是“中国罐头第一镇”，现有罐头加工及配套企业70…"
