    "description": "中国10月规模以上工业企业利润同比增长20.1%，增速较9月加快。但今年以来各行业盈利表现持续分化，电子设备制造业利润大幅增长，汽车制造业利润则显著下滑，反映中国经济复苏仍不均衡。 中国国家统计局星期五（11月27日）公布的数据显示，10月规模以上工业企业利润同比增长20.1%，高于9月的14.4%。今年首10个月，规模以上工业企业实现利润总额约6万7374亿元（人民币，下同，1.3万亿新元），同比增长16%，增速较首九个月的15.5%…",
    "content": "中国10月规模以上工业企业利润同比增长20.1%，增速较9月加快。但今年以来各行业盈利表现持续分化，电子设备制造业利润大幅增长，汽车制造业利润则显著下滑，反映中国经济复苏仍不均衡。 中国国家统计局星期五（11月27日）公布的数据显示，10月规模以上工业企业利润同比增长20.1%，高于9月的14.4%。今年首10个月，规模以上工业企业实现利润总额约6万7374亿元（人民币，下同，1.3万亿新元），同比增长16%，增速较首九个月的15.5%加快。 分行业来看，今年首10个月，采矿业利润同比增长38.8%，制造业增长17…"
