    "content": "新华社瑞士苏黎世11月26日电 “出口中国”瑞士专场活动26日在瑞士苏黎世举办。中瑞两国约120名商协会和企业代表参加活动并开展洽谈对接。 中国商务部外贸司副司长贺少军表示，瑞士是中国在欧洲值得信赖的重要合作伙伴，两国经济结构互补，合作潜力巨大。中瑞自贸协定升级议定书的签署，是中瑞两国深化双向互利合作的又一里程碑。举办“出口中国”专场活动，旨在借助自贸协定升级的优惠安排，让更多瑞士优质产品进入中国市场，惠及两国企业和人民。中方诚挚欢迎瑞士企业继续用好进博会等各类开放平台，加大优质产品和创新成果推介力度，持续拓展中国…"
