    "content": "中新网三亚11月27日电 (张月和)未来五年，三亚将如何打造国际旅游消费中心核心区？海南省委常委、三亚市委书记王祺扬在中国共产党三亚市第九次代表大会上作报告时说，三亚将坚定不移深化文旅融合，创成国家文化和旅游产业发展示范区，实现从传统旅游城市向世界级度假创业城市转型，基本建成世界一流滨海旅游目的地。"
