    "description": "新华社墨西哥城11月26日电 行走拉美手记｜在墨西哥“陶都”寻访中国青花印记 新华社记者张拓 刘宇辰 何冰 在墨西哥中部高原谷地，火山环绕间，坐落着一座明亮安静、色彩缤纷的古城——有墨西哥“陶都”之称的普埃布拉。 普埃布拉市建于1531年，火山活动赋予这里优质黏土资源。来自西班牙陶瓷重镇塔拉韦拉－德拉雷纳的工匠带来欧洲的锡釉陶技术，普埃布拉的塔拉韦拉陶瓷由此发展起来。 16世纪中叶，一艘艘满载精美瓷器、丝绸等中国商品的大帆船抵达墨西哥太…",
    "content": "新华社墨西哥城11月26日电 行走拉美手记｜在墨西哥“陶都”寻访中国青花印记 新华社记者张拓 刘宇辰 何冰 在墨西哥中部高原谷地，火山环绕间，坐落着一座明亮安静、色彩缤纷的古城——有墨西哥“陶都”之称的普埃布拉。 普埃布拉市建于1531年，火山活动赋予这里优质黏土资源。来自西班牙陶瓷重镇塔拉韦拉－德拉雷纳的工匠带来欧洲的锡釉陶技术，普埃布拉的塔拉韦拉陶瓷由此发展起来。 16世纪中叶，一艘艘满载精美瓷器、丝绸等中国商品的大帆船抵达墨西哥太平洋沿岸港口阿卡普尔科。这些商品经陆地运输，一部分运至墨西哥城集散，一部分运至大…"
