    "content": "中新社曼谷11月26日电 (记者 李映民)由中国人权研究会、中国驻泰国大使馆、中国外文局和泰国泰中文化促进委员会、亚太智库共同主办的《习近平关于尊重和保障人权论述摘编》学术研讨会26日在泰国首都曼谷举行。中泰两国50多位专家学者参加会议，围绕“人民幸福生活是最大的人权”交流研讨。"
