    "description": "当地时间11月26日，欧洲理事会提名巴勃罗·埃尔南德斯·德科斯（Pablo Hernández de Cos）为下一任欧洲央行行长。 德科斯预计将于2027年2月7日接替克里斯蒂娜·拉加德（Christine Lagarde），出任下一任欧洲央行行长。欧洲央行行长任期为8年，且不可连任。 德科斯将成为欧洲央行自1998年成立以来的第五任行长，也是首位担任这一职务的西班牙人。 与此同时，法国籍劳伦斯·布恩（Laurence Boone）和…",
    "content": "当地时间11月26日，欧洲理事会提名巴勃罗·埃尔南德斯·德科斯（Pablo Hernández de Cos）为下一任欧洲央行行长。 德科斯预计将于2027年2月7日接替克里斯蒂娜·拉加德（Christine Lagarde），出任下一任欧洲央行行长。欧洲央行行长任期为8年，且不可连任。 德科斯将成为欧洲央行自1998年成立以来的第五任行长，也是首位担任这一职务的西班牙人。 与此同时，法国籍劳伦斯·布恩（Laurence Boone）和德国籍经济学家马库斯·布伦纳迈尔（Markus Brunnermeier）也获得…"
