    "description": "新华社海牙11月26日电（记者邵海军）荷兰外贸与发展合作大臣舍尔茨玛26日表示，美国国会正在审议的《硬件技术管制多边协调法案》损害荷兰主权和国家利益。如果该法案获得通过，荷兰政府将要求美国政府不执行该法案。 舍尔茨玛当天在荷兰众议院一般性辩论发言中表示，《硬件技术管制多边协调法案》对美国盟友所施加的限制措施远超合理范围。法案一旦通过，将对荷兰半导体产业以及经济发展带来严重不利影响，荷兰坚决反对这一损害主权和利益的单边措施，将继续通过外交…",
    "content": "新华社海牙11月26日电（记者邵海军）荷兰外贸与发展合作大臣舍尔茨玛26日表示，美国国会正在审议的《硬件技术管制多边协调法案》损害荷兰主权和国家利益。如果该法案获得通过，荷兰政府将要求美国政府不执行该法案。 舍尔茨玛当天在荷兰众议院一般性辩论发言中表示，《硬件技术管制多边协调法案》对美国盟友所施加的限制措施远超合理范围。法案一旦通过，将对荷兰半导体产业以及经济发展带来严重不利影响，荷兰坚决反对这一损害主权和利益的单边措施，将继续通过外交手段与美方交涉。 舍尔茨玛还说，该法案也将损害其他欧洲国家利益，荷兰会与欧盟密切…"
