    "title": "美国感恩节强风暴来袭：暴雨、洪水、航班停飞，东海岸83万户家庭断电",
    "link": "https://m.thepaper.cn/newsDetail_forward_34571834",
    "pub_date": "2026-11-27 09:27:48",
    "author": "",
    "description": "当地时间11月26日，一场强烈风暴沿美国东海岸北上，带来暴雨、强风和沿海洪水。截至当天傍晚，全美超过83万户家庭和企业断电。马里兰、宾州等地受影响严重。强风吹倒树木和电线，暴雨叠加高潮位，导致从北卡罗来纳州到新泽西州的沿海社区出现洪水。",
    "content": "当地时间11月26日，一场强烈风暴沿美国东海岸北上，带来暴雨、强风和沿海洪水。截至当天傍晚，全美超过83万户家庭和企业断电。马里兰、宾州等地受影响严重。强风吹倒树木和电线，暴雨叠加高潮位，导致从北卡罗来纳州到新泽西州的沿海社区出现洪水。"
