    "content": "新华社哈瓦那11月26日电 记者手记｜给生活充上电：古巴社区光伏充电站见闻 新华社记者蒋彪 每天上午，伴着阳光，家住哈瓦那省塞罗市的居民玛丽拉·阿尼萨尔都会带着手机、电风扇和便携式储能电源，到家对面的光伏充电站充电。这已成为她日常生活中的固定安排。 在美国制裁下，古巴长期难以进口燃料及发电设备，发电厂设备老旧，全国电力供应紧张。今年1月初，美国对委内瑞拉发动军事打击后，进一步加大对古施压力度，威胁对向古巴提供石油的国家输美商品加征从价关税。这加剧了古巴燃油短缺，使全国电力供应状况进一步承压。 “这里经常停电，有时甚…"
