    "description": "新华社贵阳11月27日电（记者向定杰）由中国铁建投资建设运营、中国铁建大桥局等单位参建的贵州省乌当（羊昌）至长顺高速公路27日建成投入运营，进一步完善了以贵阳贵安为中心的1小时通勤圈，有效提升黔中都市高速路网承载力。 乌长高速全长约115公里，双向六车道，设计时速100公里，与兰海、沪昆、银百等多条国家高速主干线互通，是串联黔中经济区、衔接通往成渝地区双城经济圈高速干线的便捷通道。 贵州山地和丘陵占全省国土面积的92.5%。建设期间，项…",
    "content": "新华社贵阳11月27日电（记者向定杰）由中国铁建投资建设运营、中国铁建大桥局等单位参建的贵州省乌当（羊昌）至长顺高速公路27日建成投入运营，进一步完善了以贵阳贵安为中心的1小时通勤圈，有效提升黔中都市高速路网承载力。 乌长高速全长约115公里，双向六车道，设计时速100公里，与兰海、沪昆、银百等多条国家高速主干线互通，是串联黔中经济区、衔接通往成渝地区双城经济圈高速干线的便捷通道。 贵州山地和丘陵占全省国土面积的92.5%。建设期间，项目团队聚焦复杂桥梁施工、质量安全管控、长期运营养护等难题，同步推进科研攻关、专利…"
