    "author": "",
    "description": "乡村振兴，青年有为。安徽省明光市女山湖镇、自来桥镇、古沛镇的三名大学生王玉雪、王星龙、张弘扬，告别城市岗位重返故土。从直播间推介湖鲜，到智慧放牧养牛，再到无人机植保作业，他们把所学所长带到田间地头，拥抱互联网，善用新技术，带动乡亲增收，以青春力量赋能现代农业，在田野上追逐梦想，为乡村振兴注入青春动能。 统筹：李杰、李佳琳、王冰笛 编导：刘瑞娟 作者：曹力、陈喜、王卫国、张学景、洪颖贤、文建广 包装：夏勇 新华社音视频部制作",
    "content": "乡村振兴，青年有为。安徽省明光市女山湖镇、自来桥镇、古沛镇的三名大学生王玉雪、王星龙、张弘扬，告别城市岗位重返故土。从直播间推介湖鲜，到智慧放牧养牛，再到无人机植保作业，他们把所学所长带到田间地头，拥抱互联网，善用新技术，带动乡亲增收，以青春力量赋能现代农业，在田野上追逐梦想，为乡村振兴注入青春动能。 统筹：李杰、李佳琳、王冰笛 编导：刘瑞娟 作者：曹力、陈喜、王卫国、张学景、洪颖贤、文建广 包装：夏勇 新华社音视频部制作"
