    "description": "新华社耶路撒冷11月27日电（记者庞昕熠 黄耀漫）以色列国防军26日晚发表声明称，以军当天对黎巴嫩南部黎真主党武装的火箭弹及发射装置发动打击。 以军说，此次打击目标是黎南部艾因·提纳地区真主党拉德万部队一处训练营地内的数十枚火箭弹及发射装置。真主党武装人员计划使用这些火箭弹袭击以色列，以军通过空中打击“消除威胁”。 以军还说，将继续采取行动“消除威胁”，同时将“继续恪守停火协议”。",
