    "content": "中国国务院总理李强在会见亚洲开发银行行长神田真人时说，中国将与亚洲开发银行提高合作，共同促进地区发展繁荣。日本媒体报道称，首相高市早苗去年11月发表“台湾有事”论后，日中关系陷入低谷，李强此次会见神田真人实属罕见。 据中国外交部官网消息，李强星期四（11月26日）下午在北京人民大会堂会见神田真人时说，近年来，国际局势不稳定不确定因素增多，对亚洲经济造成冲击，需要各方进一步加强区域合作。亚行长期是区域经济一体化的重要推动者，中国将继续支持亚行相关工作，不断提高双方合作水平，共促地区发展繁荣。 他指出，今年以来，面对外…"
