    "content": "2026年11月27日 湖南（长沙）咖啡产业园，烘焙车间里，非洲咖啡豆随滚筒缓缓转动，醇厚香气漫开。来自乌干达、埃塞俄比亚的生豆跨越万里，在这里加工、分装，再走向全国各地。 依托今年5月起我国对53个非洲建交国全面实施的零关税举措，湖南本土咖啡品牌小咖主，把东非高原的优质豆子稳定引入国内，也把实实在在的收益送到非洲咖啡农户手中。一粒小小的咖啡豆，正是中非深化互利合作的生动缩影。 多年前，小咖主创始人景建华走访乌干达咖啡庄园时，看上当地农户精心管护的咖啡树，却发现贸易成本太高，采购不易。“以前关税摆在那里，我们采购时…"
