    "description": "2026年11月27日 “老师一定要生孩子吗？能不能保证新老师不怀孕？”很难想象，有家长会因为这样的苛刻要求实现不了而投诉在校老师。 不久前，央视新闻频道《朝闻天下》关注校园投诉乱象，家校关系被再度置于聚光灯下。出发点都是为孩子好，为何家校双方在一些问题上“剑拔弩张”？如何构建良性健康的家校关系？ 细看一些家长的投诉内容，或属于沟通失当，或存在认知偏差。比如，指责老师不应安排孩子参加古希腊悲剧讲座，因为“学习压力太大，应该多看喜剧”；即…",
    "content": "2026年11月27日 “老师一定要生孩子吗？能不能保证新老师不怀孕？”很难想象，有家长会因为这样的苛刻要求实现不了而投诉在校老师。 不久前，央视新闻频道《朝闻天下》关注校园投诉乱象，家校关系被再度置于聚光灯下。出发点都是为孩子好，为何家校双方在一些问题上“剑拔弩张”？如何构建良性健康的家校关系？ 细看一些家长的投诉内容，或属于沟通失当，或存在认知偏差。比如，指责老师不应安排孩子参加古希腊悲剧讲座，因为“学习压力太大，应该多看喜剧”；即便是教师正常管教也不认可，随意发起举报投诉。试想，广大教育工作者如果疲于应付这些…"
